// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    address originalOwner;

    function setUp() public {
        c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub()));
        originalOwner = c.owner();
    }

    function testFuzz_property(address actor, address newOwner) public {
        // keep the caller a genuine non-owner: not the test contract (deployer/owner)
        // and not a precompile/zero address
        vm.assume(actor != address(this));
        vm.assume(uint160(actor) > 10);
        vm.assume(actor != originalOwner);
        vm.assume(uint160(newOwner) > 10);

        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            // even if a call "succeeded", ownership must never have left the owner
            assertTrue(c.owner() == originalOwner, "owner changed by non-owner");
        } catch {
            // correct behavior: non-owner call reverts, owner unchanged
            assertTrue(c.owner() == originalOwner, "owner changed by non-owner");
        }
    }
}
contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}
